--   - Fruit First: Why Real Food Beats Vitamin Tablets
-- Generated by supabase/seed/build_learn.py from learn_articles.json.

insert into public.education_articles (slug, title, subtitle, category, category_label, read_minutes, author, is_featured, is_recommended, tags, conditions, body, sort_order) values
  ('confident-posture', 'Stand Tall: How Fitness and Posture Shape Your Confidence', 'Body shape, posture and strength for confidence and your career', 'presence', 'Personal Presence & Career Confidence', 5, 'VitalU health team', false, false, array['posture', 'confidence', 'fitness', 'careers', 'underweight', 'shoulders']::text[], '{}'::text[], '{"hook": "Before you say a word in an interview, the panel has already seen how you walk in, sit down and hold your shoulders. People form first impressions in a fraction of a second. The good news is that posture, strength and a healthy weight are things you can build.", "sections": [{"heading": "First impressions start with the body", "text": "In one well-known study, people judged traits such as trustworthiness and competence from a face seen for just a tenth of a second, and more time mostly made them surer of the same judgement. In job interviews, nonverbal cues such as posture, eye contact, smiling and a firm handshake shape how candidates are rated. These snap judgements are not always fair or accurate, but they are real, so it helps to make your body language work for you."}, {"heading": "Your body speaks for your personality", "text": "People read personality from the body before they hear your ideas. In a study of filmed job interviews, raters who only saw the candidates, with no sound, still judged their personality, and the visual cues mainly made candidates look more or less conscientious: organised, reliable and hard-working. Those judgements went on to shape the interview ratings. An upright, open posture tends to come across as confident, approachable and in control; slumped shoulders, a lowered head and a hunched, very thin frame are easily read as shy, tired or unsure, even when you are not. Your appearance is not your personality, but it is often the first part of it that other people meet."}, {"heading": "Posture changes how you feel, not only how you look", "text": "In a randomised trial, people who sat upright while preparing a stressful speech reported higher self-esteem, better mood and less fear than people who sat slumped. The slumped group also used more negative words when they spoke. Other studies found that sitting tall reduced tiredness in people with low mood, and made people more confident in their own positive thoughts about themselves."}, {"heading": "Slumped and rounded shoulders: why they happen", "text": "Hours bent over a phone, laptop or textbook tighten the chest muscles and weaken the upper back. Over time the shoulders roll forward, the head pokes out and the chest looks sunken. This changes your whole appearance: the shoulders look narrower than they are, you can look tired or unsure, and often brings neck and back pain. The good news: a simple programme of upper-back strengthening and chest stretching has been shown to reduce forward head and rounded shoulder posture within eight weeks."}, {"heading": "Narrow shoulders and a very thin build", "text": "How wide your shoulders are is mostly set by your skeleton, which you cannot change. What you can change is the muscle around them and how you carry them. The shoulder and upper-back muscles grow with strength training, and standing tall shows their full width. People do notice upper-body strength: in one study it explained most of the differences in how attractive men''s bodies were rated. Being very underweight (a BMI below 18.5) often means little muscle, weaker bones, tiredness and getting ill more easily, and many students feel self-conscious about looking thin or \"weak\". This is common: in one University of Peradeniya study, 27% of undergraduates were underweight."}, {"heading": "Fitness builds confidence from the inside", "text": "Regular physical activity is linked with higher self-esteem, partly because it improves how fit you feel and how you see your body, whatever your weight. Being fit also gives you the energy for long lecture days, exams, internships and later a full working day, and it shows in how you move and carry yourself. Students who feel fit and strong are more likely to speak up in class, take on leadership roles and enjoy presenting, which is how confidence grows into personality and career progress."}, {"heading": "A simple four-week plan", "text": "Do these two or three times a week. No gym is needed.", "bullets": ["Strengthen your upper back: rows with a backpack or water bottles, 3 sets of 10 to 12.", "Build the chest and shoulders: push-ups (start on your knees), and a shoulder press with water bottles.", "Open the chest: a doorway stretch, 30 seconds on each side, after long study sessions.", "Hold a plank for 20 to 40 seconds to support an upright trunk.", "Raise your laptop or phone to eye level so you do not look down for hours.", "If you are underweight, add one extra meal or snack a day with protein: eggs, dhal, peanuts, milk, fish or chicken, so the training builds muscle.", "Sleep 7 to 9 hours: muscles grow and recover while you sleep."]}, {"heading": "Carry it into interviews and work", "bullets": ["Walk in tall, with your shoulders back and down and your chin level.", "Sit back in the chair with both feet on the floor and lean slightly forward when you listen.", "Keep friendly eye contact and smile when you greet people.", "Keep your hands visible and relaxed rather than crossed over your chest."]}], "key_point": "Posture and strength are skills. A few weeks of practice can change how you look, how you feel and how you come across.", "myths": [{"myth": "Narrow shoulders cannot be changed at all.", "fact": "Bone width is fixed, but building the shoulder and upper-back muscles and standing tall make the shoulders look broader and stronger."}, {"myth": "Lifting weights makes you bulky overnight.", "fact": "Muscle grows slowly. Two or three sessions a week, with enough food and sleep, build strength and shape gradually."}], "takeaway": "Your worth is not your body shape. But standing tall, getting stronger and reaching a healthy weight can lift how you feel about yourself and how others see you.", "try_this": "Set a phone reminder three times a day: roll your shoulders back and down, lift your chest, level your chin and take three slow breaths.", "seek_help": "If you are underweight and cannot gain weight, have neck or back pain that does not go away, or worry about your body all the time, talk to a doctor, physiotherapist or counsellor at the University Health Centre.", "tools": [{"label": "Check your BMI", "route": "/tools/bmi"}, {"label": "Read: gaining weight the healthy way", "route": "/library/article/healthy-weight-gain"}, {"label": "Track your activity", "route": "/tools/activity"}], "references": [{"label": "Willis J, Todorov A. First impressions: making up your mind after a 100-ms exposure to a face. Psychological Science. 2006;17(7):592-598.", "url": "https://doi.org/10.1111/j.1467-9280.2006.01750.x"}, {"label": "Barrick MR, Shaffer JA, DeGrassi SW. What you see may not be what you get: relationships among self-presentation tactics and ratings of interview and job performance. Journal of Applied Psychology. 2009;94(6):1394-1411.", "url": "https://doi.org/10.1037/a0016532"}, {"label": "DeGroot T, Gooty J. Can nonverbal cues be used to make meaningful personality attributions in employment interviews? Journal of Business and Psychology. 2009;24(2):179-192.", "url": "https://doi.org/10.1007/s10869-009-9098-0"}, {"label": "Nair S, Sagar M, Sollers J, Consedine N, Broadbent E. Do slumped and upright postures affect stress responses? A randomized trial. Health Psychology. 2015;34(6):632-641.", "url": "https://doi.org/10.1037/hea0000146"}, {"label": "Wilkes C, Kydd R, Sagar M, Broadbent E. Upright posture improves affect and fatigue in people with depressive symptoms. Journal of Behavior Therapy and Experimental Psychiatry. 2017;54:143-149.", "url": "https://doi.org/10.1016/j.jbtep.2016.07.015"}, {"label": "Briñol P, Petty RE, Wagner B. Body posture effects on self-evaluation: a self-validation approach. European Journal of Social Psychology. 2009;39(6):1053-1064.", "url": "https://doi.org/10.1002/ejsp.607"}, {"label": "Lynch SS, Thigpen CA, Mihalik JP, Prentice WE, Padua D. The effects of an exercise intervention on forward head and rounded shoulder postures in elite swimmers. British Journal of Sports Medicine. 2010;44(5):376-381.", "url": "https://doi.org/10.1136/bjsm.2009.066837"}, {"label": "Sell A, Lukaszewski AW, Townsley M. Cues of upper body strength account for most of the variance in men''s bodily attractiveness. Proceedings of the Royal Society B. 2017;284(1869):20171819.", "url": "https://doi.org/10.1098/rspb.2017.1819"}, {"label": "Zamani Sani SH, Fathirezaie Z, Brand S, et al. Physical activity and self-esteem: testing direct and indirect relationships associated with psychological and physical mechanisms. Neuropsychiatric Disease and Treatment. 2016;12:2617-2625.", "url": "https://doi.org/10.2147/NDT.S116811"}, {"label": "American College of Sports Medicine. Progression models in resistance training for healthy adults. Medicine & Science in Sports & Exercise. 2009;41(3):687-708.", "url": "https://doi.org/10.1249/MSS.0b013e3181915670"}, {"label": "Senanayake HRV, Daundasekara DMSS. Prevalence and predictors of food insecurity among undergraduate students residing on campus: a case study at University of Peradeniya, Sri Lanka. iPURSE 2024 Proceedings, p. 227.", "url": "https://ir.lib.pdn.ac.lk/items/b4270390-b4b8-4b0d-bbb4-b8f58bcf9a4b"}]}'::jsonb, 30),
  ('fruits-first', 'Fruit First: Why Real Food Beats Vitamin Tablets', 'Vitamins, minerals, fibre and antioxidants the natural way', 'essentials', 'Everyday Health Essentials', 5, 'VitalU health team', false, false, array['fruit', 'vitamins', 'supplements', 'immunity', 'skin', 'digestion']::text[], '{}'::text[], '{"hook": "A strip of vitamin tablets can look easier than buying fruit. But a banana, a guava or a slice of papaya gives you far more than any pill: fibre, water, hundreds of natural plant compounds and real sweetness, usually for less money.", "sections": [{"heading": "What fruit gives you", "bullets": ["Vitamin C (guava, orange, papaya, mango, pineapple): for immunity, healthy skin and absorbing iron from rice and dhal.", "Vitamin A as beta-carotene (ripe papaya, mango): for your eyes and skin.", "Minerals such as potassium and magnesium (banana, papaya, avocado): for healthy blood pressure, muscles and nerves.", "Folate: needed to make new cells and red blood cells.", "Fibre: for regular bowels, a healthy gut and steadier blood sugar.", "Antioxidants and polyphenols, especially in deeply coloured fruits: protect cells from damage."]}, {"heading": "How fruit supports your body", "bullets": ["Immunity: vitamin C helps immune cells work, and low levels make infections more likely.", "Skin: vitamin C is needed to make collagen, the protein that keeps skin firm, and helps protect skin from damage.", "Digestion: fibre keeps you regular and feeds helpful gut bacteria. People who eat more fibre have less heart disease, type 2 diabetes and bowel cancer.", "Overall well-being: eating more fruit and vegetables is linked with lower risk of heart disease, stroke and early death."]}, {"heading": "Why food comes before tablets", "text": "In fruit, vitamins come packed with fibre, water and many plant compounds that work together, at natural doses. A tablet gives one or a few nutrients on their own. For healthy adults who eat reasonably well, large reviews show that multivitamins and single vitamins do not prevent heart disease or cancer. Some high-dose supplements can even harm: in a large trial, beta-carotene tablets increased lung cancer in men who smoked, while beta-carotene from fruit is not linked with this harm. Very high doses of vitamin A, vitamin D or iron can also be toxic."}, {"heading": "Whole fruit, not juice", "text": "Eating whole fruit is linked with a lower risk of type 2 diabetes, while drinking fruit juice is linked with a higher risk. Juicing removes most of the fibre, and packet juices add sugar. Eat the fruit, and drink water."}, {"heading": "Most Sri Lankan students eat too little fruit", "text": "Sri Lanka''s food-based dietary guidelines recommend 2 to 3 servings of fruit a day. In a study of rural Sri Lankan adults, fewer than 2 in 100 met the fruit recommendation. In a University of Peradeniya study, no student met the daily fruit and vegetable target."}, {"heading": "When supplements are needed", "text": "Supplements are useful when there is a real need. Use them on the advice of a doctor, pharmacist or dietitian, at the dose they recommend.", "bullets": ["A deficiency found by a blood test, for example iron-deficiency anaemia.", "Folic acid before and in early pregnancy, to protect the baby''s development.", "Vitamin B12 if you eat no animal foods at all.", "Vitamin D if a doctor finds your level is low.", "During or after an illness, or with some medicines, when a doctor advises it."]}, {"heading": "Easy ways to eat 2 to 3 fruits a day", "bullets": ["Add a banana to breakfast.", "Buy a guava or an orange from a campus stall as a between-lecture snack.", "Finish lunch with a slice of papaya or pineapple.", "Keep fruit where you can see it on your study desk.", "Choose fruit in season, such as mango or rambutan: it is cheaper and tastes better.", "Pick a different colour each day."]}], "key_point": "Fruit gives vitamins together with fibre and plant compounds that tablets cannot copy. Use supplements only when a health professional finds a need.", "myths": [{"myth": "A multivitamin makes up for a poor diet.", "fact": "Tablets do not replace fibre or the many compounds in whole foods, and large reviews show they do not prevent heart disease or cancer in healthy adults."}, {"myth": "Fruit is too sugary to eat every day.", "fact": "The sugar in whole fruit comes with fibre and water. Whole fruit is linked with a lower risk of diabetes. Juice and sweet drinks are the problem."}], "takeaway": "Two to three servings of whole fruit a day, in different colours, is one of the simplest things you can do for your immunity, skin and digestion.", "try_this": "Tomorrow, buy one fruit from a campus stall and eat it between lectures. Try a different colour every day this week.", "seek_help": "If you feel tired all the time, look pale, get infections often or have been told you are low in a vitamin or iron, see a doctor at the University Health Centre before buying supplements.", "tools": [{"label": "Check your dietary diversity", "route": "/diet/diversity"}, {"label": "Log a meal", "route": "/diet/log"}], "references": [{"label": "World Health Organization. Healthy diet. Fact sheet, 2020.", "url": "https://www.who.int/news-room/fact-sheets/detail/healthy-diet"}, {"label": "Aune D, Giovannucci E, Boffetta P, et al. Fruit and vegetable intake and the risk of cardiovascular disease, total cancer and all-cause mortality: a systematic review and dose-response meta-analysis of prospective studies. International Journal of Epidemiology. 2017;46(3):1029-1056.", "url": "https://doi.org/10.1093/ije/dyw319"}, {"label": "Carr AC, Maggini S. Vitamin C and immune function. Nutrients. 2017;9(11):1211.", "url": "https://doi.org/10.3390/nu9111211"}, {"label": "Pullar JM, Carr AC, Vissers MCM. The roles of vitamin C in skin health. Nutrients. 2017;9(8):866.", "url": "https://doi.org/10.3390/nu9080866"}, {"label": "Reynolds A, Mann J, Cummings J, et al. Carbohydrate quality and human health: a series of systematic reviews and meta-analyses. The Lancet. 2019;393(10170):434-445.", "url": "https://doi.org/10.1016/S0140-6736(18)31809-9"}, {"label": "US Preventive Services Task Force (Mangione CM, et al.). Vitamin, mineral, and multivitamin supplementation to prevent cardiovascular disease and cancer: recommendation statement. JAMA. 2022;327(23):2326-2333.", "url": "https://doi.org/10.1001/jama.2022.8970"}, {"label": "The Alpha-Tocopherol, Beta Carotene Cancer Prevention Study Group. The effect of vitamin E and beta carotene on the incidence of lung cancer and other cancers in male smokers. New England Journal of Medicine. 1994;330(15):1029-1035.", "url": "https://doi.org/10.1056/NEJM199404143301501"}, {"label": "Muraki I, Imamura F, Manson JE, et al. Fruit consumption and risk of type 2 diabetes: results from three prospective longitudinal cohort studies. BMJ. 2013;347:f5001.", "url": "https://doi.org/10.1136/bmj.f5001"}, {"label": "Abeywickrama HM, Wimalasiri KMS, Koyama Y, et al. Assessment of nutritional status and dietary pattern of a rural adult population in dry zone, Sri Lanka. International Journal of Environmental Research and Public Health. 2020;17(1):150.", "url": "https://doi.org/10.3390/ijerph17010150"}, {"label": "Ralapanawa DMPUK et al. Prevalence of metabolic syndrome and its components among university students at the University of Peradeniya. iPURSE 2023 Proceedings."}, {"label": "World Health Organization. WHO recommendations on antenatal care for a positive pregnancy experience. Geneva: WHO; 2016.", "url": "https://www.who.int/publications/i/item/9789241549912"}]}'::jsonb, 31)
